import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load card image texture
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Create plane geometry with atlas aspect ratio (512:320 ≈ 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1);
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide
  });
  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Render text content via fontAtlas
  if (ctx.fontAtlas && config.textContent && Array.isArray(config.textContent) && config.textContent.length > 0) {
    config.textContent.forEach((textItem, index) => {
      const text = typeof textItem === 'string' ? textItem : (textItem.text || '');
      const textMesh = ctx.fontAtlas.createText(text, {
        font: typeof textItem === 'string' ? 'Lora' : (textItem.font || 'Lora'),
        size: typeof textItem === 'string' ? 0.34 : (textItem.size || 0.34),
        weight: typeof textItem === 'string' ? 400 : (textItem.weight || 400),
        color: config.colors?.ink || '#16161d'
      });
      if (textMesh) {
        textMesh.position.y = -0.7 - (index * 0.3);
        group.add(textMesh);
      }
    });
  }

  // Apply scene placement from config
  const pos = config.scenePosition || {};
  group.position.set(pos.x ?? -3.2, pos.y ?? 1, pos.z ?? 0.06);

  const rot = config.sceneRotation || {};
  group.rotation.set(rot.x ?? 0, rot.y ?? 0, rot.z ?? 0);

  const scale = config.sceneScale || {};
  group.scale.set(scale.x ?? 1, scale.y ?? 1, scale.z ?? 1);

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    gsap.killTweensOf(group);
  };

  // No interactive handlers for static element
  group.userData.handlers = {};

  return group;
}
